private class FirstNodeFinder<Node
: SyntaxProtocol>: SyntaxAnyVisitor {
  let predicate: (Node) -> Bool
  var found: Node? = nil

  init(predicate: @escaping (Node) -> Bool)
{
    self.predicate = predicate
    super.init(viewMode: .sourceAccurate)
  }

  override func visitAny(_ node: Syntax) /*c*/-> SyntaxVisitorContinueKind {
    if found != nil {
      return .skipChildren
    }

    if let matchedNode = node.as(Node.self), predicate(matchedNode) {
      found = matchedNode
      return .skipChildren
    }

    return .visitChildren
  }
}

